  description: log.notes || `Work log from ${new Date(log.date).toLocaleDateString()}`,
  category: 'worklog',
  tags: [log.category, ...log.tags],
});

const buildKnowledgeResult = (entry: KnowledgeEntry): DynamicSearchItem => ({
  id: `knowledge-${entry.id}`,
