      db.shifts.orderBy('date').reverse().toArray(),
      db.tasks.orderBy('createdAt').reverse().toArray(),
    ]);
    setInvoices(savedInvoices);
    setClients(savedClients);
    setShifts(savedShifts);
    setTasks(savedTasks);
    setFormData((current) => ({
      ...current,
      clientId: current.clientId || savedClients[0]?.id || '',
    }));
  };

  useEffect(() => {
