  try {
    const parsed = JSON.parse(content) as Partial<KbFieldCard>;
    if (typeof parsed.id === 'string' && typeof parsed.title === 'string') {
      return parsed as KbFieldCard;
    }
  } catch {
    // Ignore records that are not stored KB field cards.
  }

  return null;
